base = open(os.path.join(PUB, "about.html"), encoding="utf-8").read()
head = base[:base.index("<main")]; foot = base[base.index("</main>") + len("</main>"):]
def path(l): return "/about" if l == "en" else "/%s/about" % l
def render(l):
    t = T[l]
    alts = "".join('<link rel="alternate" hreflang="%s" href="%s%s">' % (x, SITE, path(x)) for x in LANGS) + '<link rel="alternate" hreflang="x-default" href="%s/about">' % SITE
    h = re.sub(r"<html lang=\"[a-z]+\">", '<html lang="%s">' % l, head, 1)
    h = re.sub(r"<title>[^<]*</title>", "<title>%s</title>" % E(t["title"]), h, 1)
    h = re.sub(r'<meta name="description" content="[^"]*">', '<meta name="description" content="%s">' % E(t["desc"]), h, 1)
    h = re.sub(r'<link rel="canonical" href="[^"]*">(<link rel="alternate" hreflang[^>]*>)*', '<link rel="canonical" href="%s%s">%s' % (SITE, path(l), alts), h, 1)
    h = re.sub(r'"@id": "https://citedby.eu/about#page", "url": "[^"]*", "name": "[^"]*", "inLanguage": "[a-z]+"', '"@id": "https://citedby.eu%s#page", "url": "https://citedby.eu%s", "name": "%s", "inLanguage": "%s"' % (path(l), path(l), t["ln"] if l != "en" else "About CitedBy", l), h, 1)
    li = "".join("<li>%s</li>" % x for x in t["do"]); ed = "".join("<li>%s</li>" % x for x in t["ed"])
    main = ('<main id="main"><h1>%s</h1><p class="lead">%s</p>\n<h2>%s</h2><p>%s</p>\n<h2>%s</h2><ul>%s</ul>\n<h2>%s</h2><p>%s</p>\n<h2>%s</h2><p>%s</p>\n'
            '<h2 id="editorial">%s</h2><ul>%s</ul>\n<h2>%s</h2><p>%s</p>\n<h2>%s</h2><p>%s</p></main>') % (t["h1"], t["lead"], t["which_h"], t["which"], t["do_h"], li, t["not_h"], t["nota"], t["earn_h"], t["earn"], t["ed_h"], ed, t["who_h"], t["who"], t["con_h"], t["con"])
    return h + main + foot
for l in LANGS:
    out = os.path.join(PUB, path(l).lstrip("/") + ".html"); os.makedirs(os.path.dirname(out), exist_ok=True)
    open(out, "w", encoding="utf-8").write(render(l))
print("wrote", len(LANGS), "about pages")
